package com.greenocean.backend;
import com.greenocean.backend.auth.service.*;import com.greenocean.backend.auth.dto.*;import com.greenocean.backend.assistance.service.*;import com.greenocean.backend.assistance.dto.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.util.concurrent.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") class PhaseEFConcurrencyTest {
 @Autowired RegistrationService registration;@Autowired AuthenticationService auth;@Autowired AssistanceService assistance;@Autowired OutboxCipher cipher;@Autowired TokenService tokens;@Autowired JdbcTemplate db;
 String email,password="A synthetic EF concurrent passphrase";UUID user;
 @BeforeEach void setup(){email="ef-race-"+UUID.randomUUID()+"@example.test";registration.register(new RegisterRequest(email,password,null,null,null,"IR",null,null,true,1));user=db.queryForObject("SELECT id FROM users WHERE email=?",UUID.class,email);}
 @AfterEach void clean(){db.update("DELETE FROM audit_logs WHERE actor_user_id=?",user);db.update("DELETE FROM email_outbox WHERE owner_user_id=?",user);db.update("DELETE FROM users WHERE id=?",user);}
 TokenResponse login(){return auth.login(new LoginRequest(email,password,"synthetic device"));}
 void race(Runnable a,Runnable b)throws Exception{var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var one=pool.submit(()->{try{start.await();a.run();}catch(com.greenocean.backend.common.exception.UnauthorizedException expected){}catch(InterruptedException e){Thread.currentThread().interrupt();}});var two=pool.submit(()->{try{start.await();b.run();}catch(com.greenocean.backend.common.exception.UnauthorizedException expected){}catch(InterruptedException e){Thread.currentThread().interrupt();}});start.countDown();one.get(20,TimeUnit.SECONDS);two.get(20,TimeUnit.SECONDS);}}
 @Test @Tag("creative") void logoutRacingRefreshLeavesNoUsableSession()throws Exception{var old=login();race(()->auth.refresh(old.refreshToken()),()->auth.logout(old.refreshToken()));assertThat(db.queryForObject("SELECT count(*) FROM user_sessions WHERE user_id=? AND revoked_at IS NULL",Integer.class,user)).isZero();}
 @Test @Tag("malicious") void remoteRevokeRacingRefreshLeavesNoUsableSession()throws Exception{var old=login();UUID session=db.queryForObject("SELECT id FROM user_sessions WHERE user_id=?",UUID.class,user);race(()->auth.refresh(old.refreshToken()),()->auth.revokeSession(user,session));assertThat(db.queryForObject("SELECT revoked_at IS NOT NULL FROM user_sessions WHERE id=?",Boolean.class,session)).isTrue();}
 @Test @Tag("confused") void passwordResetRacingRefreshCannotResurrectSession()throws Exception{var old=login();assistance.requestPasswordReset(new EmailRequest(email));String reset=cipher.decrypt(db.queryForObject("SELECT payload->>'encrypted' FROM email_outbox WHERE owner_user_id=? AND template_key='password-reset'",String.class,user));race(()->auth.refresh(old.refreshToken()),()->assistance.resetPassword(new ResetPasswordRequest(reset,"A different EF concurrent password")));assertThat(db.queryForObject("SELECT count(*) FROM user_sessions WHERE user_id=? AND revoked_at IS NULL",Integer.class,user)).isZero();assertThatThrownBy(()->auth.refresh(old.refreshToken())).isInstanceOf(com.greenocean.backend.common.exception.UnauthorizedException.class);}
 @Test @Tag("malicious") void twoResetConsumersHaveOneWinnerAndOneConsumption()throws Exception{assistance.requestPasswordReset(new EmailRequest(email));String reset=cipher.decrypt(db.queryForObject("SELECT payload->>'encrypted' FROM email_outbox WHERE owner_user_id=? AND template_key='password-reset'",String.class,user));var start=new CountDownLatch(1);var winners=new java.util.concurrent.atomic.AtomicInteger();try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->consume(reset,start,winners));var b=pool.submit(()->consume(reset,start,winners));start.countDown();a.get(20,TimeUnit.SECONDS);b.get(20,TimeUnit.SECONDS);}assertThat(winners.get()).isEqualTo(1);assertThat(db.queryForObject("SELECT count(*) FROM password_reset_tokens WHERE user_id=? AND used_at IS NOT NULL",Integer.class,user)).isEqualTo(1);}
 void consume(String token,CountDownLatch start,java.util.concurrent.atomic.AtomicInteger winners){try{start.await();assistance.resetPassword(new ResetPasswordRequest(token,"A different EF reset passphrase"));winners.incrementAndGet();}catch(IllegalArgumentException expected){}catch(InterruptedException e){Thread.currentThread().interrupt();}}
 @Test @Tag("confused") void expiredSessionCannotIssueNewTokens(){var old=login();db.update("UPDATE user_sessions SET overall_expires_at=CURRENT_TIMESTAMP WHERE user_id=?",user);assertThatThrownBy(()->auth.refresh(old.refreshToken())).isInstanceOf(com.greenocean.backend.common.exception.UnauthorizedException.class);assertThat(db.queryForObject("SELECT refresh_token_hash FROM user_sessions WHERE user_id=?",String.class,user)).isEqualTo(tokens.hashRefreshToken(old.refreshToken()));}
}
